    ////////////////////////////////////////////////////////
    //
    // Twist
    //
    aIngress = 0xC1F547EE956269CAULL;
    aCarry = 0xDD647B68B6726D0DULL;
    aWandererA = 0xF29D3A1364B9DC11ULL;
    aWandererB = 0xF07D160F704D2DDEULL;
    aWandererC = 0xE4B0D2771FA5B02AULL;
